                className="w-full py-3 rounded-xl bg-gradient-to-r from-blue-900 to-blue-500 transition duration-300 shadow-lg shadow-blue-900/30 flex items-center justify-center gap-2 font-semibold"
              >
                Send Message
                <FaPaperPlane />
              </motion.button>
            </form>
          </motion.div>
        </div>
      </div>
    </section>
  );
}

